package com.apnishadi.ai;
import com.apnishadi.auth.CurrentAccount; import com.apnishadi.match.MatchReport; import com.apnishadi.match.MatchReportService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai") public class AiController { private final MatchReportService reports; private final AiAdvisorService advisor; public AiController(MatchReportService r,AiAdvisorService a){reports=r;advisor=a;} @PostMapping("/chat") public AiChatResponse chat(@Valid @RequestBody AiChatRequest r){CurrentAccount.requireOwnProfile(r.profileOneId()); MatchReport report=reports.createCalculatedReport(CurrentAccount.profileId(),r.profileTwoId()); return advisor.chat(report.profileOne(),report.profileTwo(),r.message(),report);} }
